def claim(db, token, now):
    with db:
        return db.execute("UPDATE jobs SET token=?, expires=?, attempts=attempts+1 WHERE id=(SELECT id FROM jobs WHERE status='pending' AND expires < ? AND attempts < 3 ORDER BY id LIMIT 1) RETURNING id, payload", (token, now+60, now)).fetchone()

def finish(db, job_id, token):
    with db:
        return db.execute("UPDATE jobs SET status='done' WHERE id=? AND token=?", (job_id, token)).rowcount

