def place_order(db, orders, inventory, billing, request):
    with db.transaction() as transaction:
        reservation = inventory.reserve(transaction, request.items)
        invoice = billing.invoice(transaction, request.customer, reservation.total)
        return orders.complete(transaction, reservation.id, invoice.id)

